const params=new URLSearchParams(location.search),raw=params.get('plan');
const plan=raw!==null&&/^[0-2]$/.test(raw)?Number(raw):null;
let lang=params.get('lang')==='en'?'en':'zh';
const strings={zh:{title:'确认订单',subtitle:'请核对套餐信息。本页面仅供确认，尚不支持付款。',back:'← 返回套餐',toggle:'EN',labels:['套餐','翻译额度','购买方式','套餐金额（人民币草案价）'],names:['轻量包','常用包','进阶包'],units:['50,000 计费字符','150,000 计费字符','500,000 计费字符'],prices:['¥19.00','¥49.00','¥149.00'],once:'单次购买 · 不自动续费',methods:'支付方式',pending:'（待开通）',notice:'支付渠道尚未开通，暂不可付款。当前不会创建正式订单、扣款或发放翻译额度。',pay:'支付暂不可用',terms:'每份 DOCX、PPTX、PDF 最低消耗 50,000 计费字符，长文档按实际计费量消耗。价格为草案，税费及有效期将在正式销售前明确。',invalid:'未找到套餐',invalidNote:'请返回套餐列表，重新选择。'},en:{title:'Confirm your order',subtitle:'Review your credit pack. Payments are not yet available.',back:'← Back to credit packs',toggle:'中文',labels:['Credit pack','Translation credits','Purchase type','Pack price (provisional USD)'],names:['Light','Everyday','Plus'],units:['50,000 billable characters','150,000 billable characters','500,000 billable characters'],prices:['$2.49','$6.49','$19.99'],once:'One-time purchase · No automatic renewal',methods:'Payment methods',pending:'(Not activated)',notice:'Payment channels are not activated. No actual order will be created, no payment taken and no credits granted.',pay:'Payments unavailable',terms:'Each DOCX, PPTX or PDF uses at least 50,000 billable characters. Longer documents use the actual billed amount. Prices are provisional; tax and credit validity will be confirmed before sales open.',invalid:'Pack not found',invalidNote:'Go back and choose a credit pack.'}};
function render(){const c=strings[lang];document.documentElement.lang=lang==='en'?'en':'zh-CN';document.title=c.title+' · SlideBridge';for(const id of ['title','subtitle','back','toggle','methods','notice','pay','terms'])document.getElementById(id).textContent=c[id];document.querySelectorAll('.pending').forEach(el=>el.textContent=c.pending);const list=document.getElementById('details');list.replaceChildren();if(plan===null){document.getElementById('title').textContent=c.invalid;document.getElementById('subtitle').textContent=c.invalidNote;return}const values=[c.names[plan],c.units[plan],c.once,c.prices[plan]];c.labels.forEach((label,i)=>{const row=document.createElement('div');row.className='row';const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=values[i];if(i===3)dd.className='price';row.append(dt,dd);list.append(row)})}
document.getElementById('toggle').onclick=()=>{lang=lang==='en'?'zh':'en';try{localStorage.setItem('uiLanguage',lang)}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render()};
document.getElementById('back').onclick=()=>{try{localStorage.setItem('uiLanguage',lang)}catch{}};
render();
